"""Read-only, bookmarkable production node output pages."""

OUTPUT_CSS = '''
body.task-page .heading,body.task-page #main>section:first-of-type{display:none}
body.task-page .detail{margin-top:0}.detail-node{text-decoration:none;color:inherit}
.detail-node[aria-current=page]{border:2px solid #246646;background:#f1f8f2}
.node-output{margin-top:22px;border-top:1px solid #dedfdb;padding-top:20px}
.node-output p,.node-output small{overflow-wrap:anywhere;line-height:1.6}
.output-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}
.output-card{overflow-wrap:anywhere;border:1px solid #dedfdb;border-radius:10px;padding:14px;min-width:0}
.output-card img{width:100%;height:210px;object-fit:contain;background:#f7f7f5}
.search-thumbnail{display:block;width:100%;min-height:210px;padding:0;border:0;background:#f7f7f5;cursor:zoom-in;border-radius:6px;overflow:hidden}.search-thumbnail img{display:block}.search-hits{white-space:pre-line;font-size:13px;margin-bottom:0}
.output-card small{display:block;color:#69736b}.output-terms{display:flex;flex-wrap:wrap;gap:8px;padding:0;list-style:none}
.output-terms li{background:#edf4ef;border-radius:6px;padding:6px 10px}
.output-actions{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}
.node,.detail-head a{color:#246646;text-decoration:none}td:last-child a{white-space:nowrap}
'''

OUTPUT_JS = r'''
function nodeURL(taskId,node='expansion'){return '/production?'+new URLSearchParams({task:taskId,node})}
function selectLine(id){location.assign(nodeURL(id))}
const outputPage={epoch:0,urls:new Set(),abort:null};
function releaseOutputs(){if(typeof assetViewer!=='undefined'&&$('asset-viewer').open)$('asset-viewer').close();outputPage.epoch++;outputPage.abort?.abort();for(const url of outputPage.urls)URL.revokeObjectURL(url);outputPage.urls.clear()}
window.addEventListener('pagehide',releaseOutputs);
function outputText(parent,tag,text){const el=document.createElement(tag);el.textContent=text??'未知';parent.append(el);return el}
function outputTerms(parent,terms){const list=document.createElement('ul');list.className='output-terms';for(const term of terms)outputText(list,'li',typeof term==='string'?term:JSON.stringify(term));parent.append(list)}
function confirmedSpec(revisions,revision){const match=revisions.items?.find(item=>item.revision===revision);if(!match?.proposal?.query_spec)throw new Error('未找到当前正式版本的确认清单，不使用草稿替代');return match}
function refillStopText(reason){return({TARGET_MET:'已达到目标',INPUT_SCOPE_COMPLETE:'固定输入范围已处理完',EXECUTION_LIMIT_REACHED:'已达到补数轮次上限',VLM_CALL_LIMIT_REACHED:'已达到 VLM 调用预算',NO_PROGRESS:'连续补数没有新增有效结果',SEARCH_STRATEGIES_EXHAUSTED:'当前批准的检索策略已耗尽',NEED_USER_INPUT:'等待发起人确认',REFILL_SCHEDULED:'已进入自动补数调度'})[reason]||reason||'继续执行'}
function renderExpansion(parent,record){const spec=record.proposal.query_spec,expansion=spec.grouped_expansion;outputText(parent,'h3','已确认的扩词清单');outputText(parent,'p',`正式版本 ${record.revision} · ${spec.raw_request||''}`);outputText(parent,'small','确认摘要：'+record.proposal_digest);if(!expansion?.groups?.length){outputText(parent,'p','此版本没有保存分组扩词；已保存的检索种子如下。');outputTerms(parent,spec.query_seeds||[]);return}const grid=document.createElement('div');grid.className='output-grid';parent.append(grid);for(const group of expansion.groups){const box=document.createElement('article');box.className='output-card';grid.append(box);outputText(box,'h4',group.primary_label);outputText(box,'p',`辅助词 ${group.auxiliary_terms.length} 个 · 包名称：${group.package_name||'未指定'}`);outputTerms(box,group.auxiliary_terms);if(!group.auxiliary_terms.length)outputText(box,'p','没有辅助扩词；使用主词检索。')}outputText(parent,'small','词表摘要：'+expansion.plan_digest)}
async function outputImage(taskId,item,card,button,token){button.disabled=true;button.textContent='加载缩略图…';try{const response=await fetch(card._asset.url,{headers,cache:'no-store',signal:outputPage.abort.signal});if(!response.ok)throw new Error('图片读取失败或授权已失效');const blob=await response.blob();if(!['image/jpeg','image/png'].includes(blob.type)||blob.size>10*1024*1024)throw new Error('图片格式或大小无效');if(token!==outputPage.epoch||!card.isConnected)return;const url=URL.createObjectURL(blob);outputPage.urls.add(url);const img=document.createElement('img');img.alt='检索图片，点击查看详情';img.src=url;img.onerror=()=>{URL.revokeObjectURL(url);outputPage.urls.delete(url);button.replaceChildren();button.textContent='图片解码失败，点击重试';button.onclick=()=>outputImage(taskId,item,card,button,token)};button.textContent='';button.replaceChildren(img);button.disabled=false;button.onclick=()=>openAssetViewer(card)}catch(error){if(token===outputPage.epoch&&card.isConnected&&error.name!=='AbortError'){button.disabled=false;button.textContent=error.message+'，点击重试';button.onclick=()=>outputImage(taskId,item,card,button,token)}}}
function createSearchCard(grid,taskId,item,token){
 const card=document.createElement('article');card.className='output-card';grid.append(card);
 card._sources=new Map();card._libs=new Set();
 card._asset={title:'检索候选 · '+(item.candidate_id||item.vector_id),url:item.preview_status==='available'&&item.preview_ref?`/v1/retrieval/tasks/${encodeURIComponent(taskId)}/candidates/${encodeURIComponent(item.candidate_id)}/preview?ref=${encodeURIComponent(item.preview_ref)}`:null,lines:()=>['状态：原始候选，尚不代表清洗通过或正式入选','素材编号：'+(item.media_unit_id||'未知'),'素材版本：'+(item.asset_version||'未知'),'解析状态：'+(item.status||'未知'),'来源：'+([...card._libs].join('、')||'未知'),...Array.from(card._sources.values(),hit=>`检索词：${hit.term} · 分数：${hit.score??'未知'}`)]};
 const thumb=outputText(card,'button','暂无可用缩略图');thumb.className='search-thumbnail';thumb.setAttribute('aria-label','查看图片与详情');thumb.onclick=()=>openAssetViewer(card);
 card._hitLine=outputText(card,'p','');card._hitLine.className='search-hits';
 if(card._asset.url)outputImage(taskId,item,card,thumb,token);
 return card;
}
function addSearchHit(card,item){
 const term=item.query_text||item.source_term||'未知',score=typeof item.score==='number'&&Number.isFinite(item.score)?item.score:null;
 const key=JSON.stringify([term,item.query_role,item.source_term,score]);
 card._sources.set(key,{term,score});if(item.library_id)card._libs.add(item.library_id);
 card._hitLine.textContent=Array.from(card._sources.values(),hit=>`检索词：${hit.term}\n分数：${hit.score===null?'未知':hit.score.toFixed(4)}`).join('\n\n');
}
function mountSearch(parent,taskId,token){outputText(parent,'h3','检索输出 · 原始候选');outputText(parent,'p','检索命中不等于清洗通过或有效素材；同一图片的多个命中合并展示，保留命中词和来源。');const controls=document.createElement('div');controls.className='output-actions';parent.append(controls);const select=document.createElement('select');select.setAttribute('aria-label','按检索词筛选');const all=outputText(select,'option','全部检索词');all.value='';controls.append(select);const status=outputText(parent,'p','读取检索结果…'),grid=document.createElement('div'),more=outputText(parent,'button','加载更多结果');grid.className='output-grid';parent.insertBefore(grid,more);let cursor=null,version=null,busy=false,request=0,retryReset=false;const cards=new Map();
 async function read(reset=false){if(busy&&!reset)return;const seq=++request;retryReset=reset;busy=true;more.disabled=true;status.textContent='读取检索结果…';const query=new URLSearchParams({limit:'24',query:select.value});if(!reset&&cursor)query.set('cursor',cursor);try{const data=await api(`/v1/retrieval/tasks/${encodeURIComponent(taskId)}/candidates?${query}`);if(token!==outputPage.epoch||seq!==request)return;if(!reset&&version&&data.search_version!==version){for(const img of grid.querySelectorAll('img')){URL.revokeObjectURL(img.src);outputPage.urls.delete(img.src)}grid.replaceChildren();cards.clear();version=null;cursor=null;retryReset=true;throw new Error('检索版本已更新，请重试读取当前版本')}if(reset){if(typeof assetViewer!=='undefined'&&$('asset-viewer').open)$('asset-viewer').close();for(const img of grid.querySelectorAll('img')){URL.revokeObjectURL(img.src);outputPage.urls.delete(img.src)}grid.replaceChildren();cards.clear()}version=data.search_version;cursor=data.next_cursor;retryReset=false;more.textContent='加载更多结果';for(const term of data.query_terms||[]){if(!Array.from(select.options).some(option=>option.value===term)){const option=outputText(select,'option',term);option.value=term}}for(const item of data.items||[]){const key=JSON.stringify([item.candidate_id||item.vector_id,item.asset_version,item.candidate_id?null:item.library_id]);let card=cards.get(key);if(!card){card=createSearchCard(grid,taskId,item,token);cards.set(key,card)}addSearchHit(card,item)}status.textContent=`原始命中 ${data.raw_hit_count??'未知'} · 本页已加载 ${cards.size} 个素材${cards.size?'':' · 当前筛选无结果'}`;more.hidden=!cursor}catch(error){if(token===outputPage.epoch&&seq===request){status.textContent='检索结果读取失败（不代表尚未开始）：'+error.message;more.hidden=false;more.textContent='重试读取'}}finally{if(seq===request){busy=false;more.disabled=false}}}
 select.onchange=()=>read(true);more.onclick=()=>read(retryReset||!version);read(true);
}
async function showNodeOutput(item){releaseOutputs();outputPage.abort=new AbortController();const token=outputPage.epoch,body=$('detail-body'),parent=document.createElement('section');parent.className='node-output';parent.setAttribute('aria-live','polite');body.append(parent);const requested=new URLSearchParams(location.search).get('node'),node=Object.hasOwn(nodeNames,requested)?requested:'expansion';for(const card of body.querySelectorAll('.detail-node')){const key=card.dataset.node;if(key===node)card.setAttribute('aria-current','page')}
 const base='/v1/retrieval/tasks/'+encodeURIComponent(item.task_id);try{if(node==='retrieval'){mountSearch(parent,item.task_id,token);return}if(node==='cleaning'){outputText(parent,'h3','清洗输出');outputText(parent,'p','查看每步输入、保留、淘汰、待复核，以及逐图原因、模型和指令快照。');mountBoardCleaning(item,parent);openBoardCleaning(item.task_id);return}if(node==='packaging'){const data=await api(base+'/delivery');if(token!==outputPage.epoch)return;outputText(parent,'h3','打包输出');if(!data.available){outputText(parent,'p','当前没有可读取的交付包。节点状态不代表已经生成交付文件。');return}for(const [label,key] of [['包 ID','package_id'],['状态','status'],['清单摘要','manifest_digest']])outputText(parent,'p',label+'：'+(data[key]??'未记录'));outputText(parent,'p',`合格唯一素材：${data.manifest?.eligible_unique_count??'未知'} · 入选图片：${data.manifest?.accepted_count??'未知'} · SHA-256 自动合并：${data.manifest?.exact_duplicate_count??'未知'} · 包内图片文件：${data.manifest?.packaged_file_count??'未知'}`);outputText(parent,'p','去重规则：SHA-256 完全一致自动合并，无需人工复核。');for(const member of data.manifest?.members||[]){const libraries=[...new Set((member.retrieval_sources||[]).map(source=>source.library_id).filter(Boolean))];outputText(parent,'p',`${member.file} · ${member.candidate_id} · ${member.content_digest} · SHA-256 精确重复副本 ${Math.max(0,(member.candidate_ids?.length||1)-1)} · 融合来源 ${member.retrieval_sources?.length||0}${libraries.length?'（'+libraries.join('、')+'）':''}`)}return}const revisions=await api(base+'/revisions');if(token!==outputPage.epoch)return;const record=confirmedSpec(revisions,item.progress.revision);if(node==='expansion')renderExpansion(parent,record);else{const [result,refill]=await Promise.all([api(base+'/results?view=accepted&limit=1'),api(base+'/refill')]);if(token!==outputPage.epoch)return;const policy=record.proposal.query_spec.refill_policy,execution=refill.execution||{};outputText(parent,'h3','补数输出');outputText(parent,'p',`目标 ${result.target_count??item.progress.counts.target} · 当前缺口 ${result.counts?.gap??'未知'} · 有效素材 ${item.progress.counts.accepted??'未知'}`);outputText(parent,'p',policy.mode==='maintain_target'?`自动补数：${policy.progression==='auto'?'已启用':'逐轮确认'} · 批准素材库：${policy.approved_library_ids.join('、')}`:'固定输入：数量不足时接受减少，不自动检索补数');outputText(parent,'p',`状态：${refillStopText(refill.stop_reason)} · 已发 ${execution.issued_rounds??0} 轮 · 已完成 ${execution.completed_rounds??0} 轮 · 连续无进展 ${execution.stagnant_rounds??0} 轮 · VLM 调用 ${execution.vlm_calls??0}`);outputText(parent,'p',`执行限制：轮次 ${execution.max_rounds??'不限'} · VLM 调用 ${execution.max_vlm_calls??'不限'} · 连续无进展 ${execution.no_progress_rounds??'未知'} 轮停止`);const rounds=execution.rounds||[];if(rounds.length){outputText(parent,'h4','逐轮证据');const grid=document.createElement('div');grid.className='output-grid';parent.append(grid);for(const round of rounds){const box=document.createElement('article');box.className='output-card';grid.append(box);outputText(box,'strong',`第 ${round.iteration} 轮 · ${round.outcome}`);outputText(box,'p',`增量候选 ${round.candidate_count} · 新增唯一有效 ${round.new_unique_accepted??'待结果'} · 累计有效 ${round.accepted_after??round.baseline_accepted} · VLM 调用 ${round.vlm_calls}`)}}else outputText(parent,'p','尚未产生补数轮次。');outputText(parent,'p','补数完成只按 SHA-256 累计去重后的有效素材计算，不把检索原始数量计为完成。')}}catch(error){if(token===outputPage.epoch){outputText(parent,'p','节点输出读取失败：'+error.message);const retry=outputText(parent,'button','重试读取节点');retry.onclick=()=>loadDetailPage();const chat=outputText(parent,'a','继续此 Chat');chat.href='/chat?task='+encodeURIComponent(item.task_id)}}}
async function loadDetailPage(){document.body.classList.add('task-page');$('line-detail').classList.remove('hidden');$('detail-chat').href='/chat?task='+encodeURIComponent(selected);$('detail-close').textContent='返回线路总览';$('detail-close').onclick=()=>location.assign('/production');$('detail-status').textContent='读取当前线路…';const taskId=selected;try{const base='/v1/retrieval/tasks/'+encodeURIComponent(taskId),task=await api(base),progress=await api(base+'/progress');const item={...task,title:'线路详情',progress};const revisions=await api(base+'/revisions');const record=confirmedSpec(revisions,progress.revision);item.title=record.proposal.query_spec.raw_request||taskId;const latest=await api(base);if(latest.task_version!==task.task_version)throw new Error('任务版本已变化，请刷新后重试');showDetail(item);await showNodeOutput(item)}catch(error){$('detail-status').textContent='线路详情读取失败：'+error.message;$('detail-body').replaceChildren();const retry=outputText($('detail-body'),'button','重试读取线路');retry.onclick=loadDetailPage}}
function startProduction(){if(selected)loadDetailPage();else load()}

'''
